#include <stdio.h>

int main() {
    int a[6];
    for (int i = 0; i < 6; i++) {
        scanf("%d", &a[i]);
    }

    int sum = 0;
    for (int i = 0; i < 6; i++) {
        sum += a[i];
    }

    if (sum % 3 != 0) {
        printf("N\n");
        return 0;
    }

    int target = sum / 3;

    for (int i = 0; i < 6; i++) {
        if (a[i] != target) continue;

        for (int j = 0; j < 6; j++) {
            if (j == i) continue;

            for (int k = j + 1; k < 6; k++) {
                if (k == i) continue;

                if (a[j] + a[k] == target) {
                    printf("S\n");
                    return 0;
                }
            }
        }
    }

    printf("N\n");
    return 0;
}
